<section class="meta"><div><b>Período</b><?=isset($dates[0])?date('d/m/Y',strtotime(min($dates))).' a '.date('d/m/Y',strtotime(max($dates))):'—'?></div><div><b>Hemocomponente</b><?=htmlspecialchars(implode(', ',$componentNames)?:'—')?></div><div><b>Processamento / origem</b><?=htmlspecialchars(implode(', ',$originNames)?:'—')?></div><div><b>Data de geração do mapa</b><?=date('d/m/Y H:i')?></div></section>
