<script>
(()=>{const body=document.body,source=document.querySelector('.report-source'),pages=document.querySelector('.print-pages');
const newPage=first=>{const page=document.createElement('section');page.className='print-page';page.append(source.querySelector('.report-header').cloneNode(true));if(first)page.append(source.querySelector('.meta').cloneNode(true));const table=document.createElement('table');table.append(source.querySelector('colgroup').cloneNode(true),source.querySelector('thead').cloneNode(true),document.createElement('tbody'));page.append(table);const footer=source.querySelector('.report-footer').cloneNode(true),number=document.createElement('span');number.className='page-number';footer.insertBefore(number,footer.lastElementChild);page.append(footer);pages.append(page);return page};
const overflows=page=>page.scrollHeight>page.clientHeight+1;
const paginate=()=>{pages.replaceChildren();body.classList.add('preparing-print');let page=newPage(true);for(const row of source.querySelectorAll('tbody tr')){const copy=row.cloneNode(true);page.querySelector('tbody').append(copy);if(overflows(page)){copy.remove();page=newPage(false);page.querySelector('tbody').append(copy)}}const all=[...pages.querySelectorAll('.print-page')],total=all.length;all.forEach((item,index)=>item.querySelector('.page-number').textContent=`Página ${index+1} de ${total}`);body.classList.remove('preparing-print');body.classList.add('print-ready')};
addEventListener('beforeprint',paginate);addEventListener('afterprint',()=>{body.classList.remove('print-ready');pages.replaceChildren()});
})();
</script></body></html>
